ALTER TABLE public.league_results DROP CONSTRAINT league_results_status_check;
ALTER TABLE public.league_results ADD CONSTRAINT league_results_status_check CHECK (((status IS NULL) OR (status = ANY (ARRAY['classified'::text, 'ret'::text, 'dnf'::text, 'dns'::text, 'dsq'::text, 'nt'::text, 'joiner'::text]))));